import java.util.Scanner;

public class Main {
    static long countDigits(long num) {
        num = (num < 0) ? -num : num;
        long count = 0;
        while (num != 0) {
            ++count;
            num /= 10;
        }
        return count;
    }

    static long generateOnes(long length) {
        long result = 0;
        for (int i = 0; i < length; ++i)
            result = 10 * result + 1;
        return result;
    }

    static long recursiveAux2(long num) {
        if (num == 0) return 0;
        num = (num < 0) ? -num : num;
        long digits = countDigits(num);
        return digits + recursiveAux2(num - generateOnes(digits));
    }

    static long recursiveAux(long num, long sign, long accumulated, long max_value, int[] state) {
        if (accumulated >= max_value) return max_value;
        if (num == 0) return accumulated;
        if (num < 0) { num = -num; sign = -sign; }
        long d = countDigits(num);
        long ones_d = generateOnes(d);
        long res_option1 = max_value, res_option2 = max_value;

        if (0 <= state[(int)d] * sign && -10 < state[(int)d]) {
            if (state[(int)d] < 10) {
                state[(int)d] += sign;
                res_option1 = recursiveAux(num - ones_d, sign, accumulated + d, max_value, state);
                state[(int)d] -= sign;
            }
        }
        if (0 <= state[(int)(d + 1)] * sign && -10 < state[(int)(d + 1)]) {
            if (state[(int)(d + 1)] < 10) {
                state[(int)(d + 1)] += sign;
                res_option2 = recursiveAux(num - 10 * ones_d - 1, sign, accumulated + d + 1, res_option1, state);
                state[(int)(d + 1)] -= sign;
            }
        }
        return res_option1 < res_option2 ? res_option1 : res_option2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int[] state = new int[20];
        System.out.println(recursiveAux(n, 1, 0, recursiveAux2(n), state));
        sc.close();
    }
}
